Save the following as `bogie-test-stand.html` and open it in a modern browser. It uses only the Three.js core ES module from cdnjs and includes custom orbit, pan, zoom, animation, and camera controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Bogie Roller Test Stand</title>

  <style>
    :root {
      --bg: #071019;
      --panel: rgba(10, 21, 31, 0.82);
      --panel-border: rgba(151, 195, 214, 0.16);
      --text: #e8f3f7;
      --muted: #8fa8b4;
      --cyan: #58d9ef;
      --green: #65e6a5;
      --amber: #ffc857;
      --red: #ff6577;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system,
        BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    button,
    input {
      font: inherit;
    }

    #viewport,
    #viewport canvas {
      position: fixed;
      inset: 0;
      width: 100%;
      height: 100%;
    }

    #viewport canvas {
      display: block;
      touch-action: none;
      outline: none;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at 50% 42%, transparent 42%, rgba(0, 0, 0, 0.4) 100%),
        linear-gradient(180deg, rgba(0, 0, 0, 0.2), transparent 22%, transparent 76%, rgba(0, 0, 0, 0.35));
    }

    .topbar {
      position: fixed;
      top: 22px;
      left: 24px;
      right: 24px;
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      pointer-events: none;
      z-index: 10;
    }

    .brand {
      max-width: 520px;
      padding: 17px 20px;
      border: 1px solid var(--panel-border);
      border-radius: 15px;
      background: linear-gradient(135deg, rgba(12, 27, 39, 0.9), rgba(8, 17, 25, 0.72));
      box-shadow: 0 18px 50px rgba(0, 0, 0, 0.26);
      backdrop-filter: blur(16px);
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 9px;
      margin-bottom: 7px;
      color: var(--cyan);
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.19em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: var(--green);
      box-shadow: 0 0 12px var(--green);
      content: "";
    }

    h1 {
      margin: 0;
      font-size: clamp(22px, 3vw, 34px);
      line-height: 1.05;
      letter-spacing: -0.035em;
    }

    .subtitle {
      margin-top: 8px;
      color: var(--muted);
      font-size: 12px;
    }

    .top-actions {
      display: flex;
      align-items: stretch;
      gap: 10px;
      pointer-events: auto;
    }

    .pill {
      min-height: 38px;
      padding: 0 14px;
      border: 1px solid var(--panel-border);
      border-radius: 11px;
      background: var(--panel);
      box-shadow: 0 12px 35px rgba(0, 0, 0, 0.2);
      backdrop-filter: blur(14px);
    }

    .pill-label {
      display: block;
      color: var(--muted);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .pill-value {
      display: block;
      margin-top: 3px;
      color: var(--text);
      font-size: 14px;
      font-weight: 700;
      letter-spacing: 0.04em;
    }

    .panel {
      position: fixed;
      z-index: 10;
      border: 1px solid var(--panel-border);
      border-radius: 15px;
      background: var(--panel);
      box-shadow: 0 18px 50px rgba(0, 0, 0, 0.26);
      backdrop-filter: blur(16px);
    }

    .panel-title {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin: 16px 18px 12px;
      color: #b9cbd4;
      font-size: 10px;
      font-weight: 800;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .panel-title span:last-child {
      color: var(--muted);
      font-size: 9px;
    }

    .data-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
    }

    .data-item {
      min-width: 0;
      padding: 12px;
      border: 1px solid rgba(151, 195, 214, 0.1);
      border-radius: 10px;
      background: rgba(255, 255, 255, 0.025);
    }

    .data-item span:first-child {
      display: block;
      margin-bottom: 5px;
      color: var(--muted);
      font-size: 9px;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .data-item strong {
      display: block;
      overflow: hidden;
      color: var(--text);
      font-size: 17px;
      font-weight: 650;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .data-item strong small {
      color: var(--muted);
      font-size: 10px;
      font-weight: 500;
    }

    .control-panel {
      left: 24px;
      bottom: 24px;
      width: 285px;
      padding: 16px;
    }

    .control-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin: 12px 0;
    }

    .control-row label {
      color: var(--muted);
      font-size: 11px;
    }

    input[type="range"] {
      width: 100%;
      accent-color: var(--cyan);
      cursor: pointer;
    }

    .button-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8px;
      margin-top: 16px;
    }

    button {
      min-height: 38px;
      border: 1px solid rgba(151, 195, 214, 0.17);
      border-radius: 9px;
      background: rgba(255, 255, 255, 0.055);
      color: var(--text);
      cursor: pointer;
      font-size: 11px;
      font-weight: 700;
      transition: background 150ms ease, border-color 150ms ease, transform 150ms ease;
    }

    button:hover {
      border-color: rgba(88, 217, 239, 0.5);
      background: rgba(88, 217, 239, 0.12);
    }

    button:active {
      transform: translateY(1px);
    }

    button.primary {
      border-color: rgba(88, 217, 239, 0.45);
      background: linear-gradient(135deg, #75dce9, #43b8cc);
      color: #062029;
    }

    button.primary:hover {
      background: linear-gradient(135deg, #91e7ef, #54c5d6);
    }

    .view-row {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 7px;
      margin-top: 14px;
    }

    .view-row button {
      padding: 8px 5px;
      font-size: 10px;
    }

    .profile {
      right: 24px;
      bottom: 24px;
      width: 285px;
      padding: 16px;
    }

    .profile-line {
      height: 3px;
      margin-bottom: 13px;
      overflow: hidden;
      border-radius: 3px;
      background: rgba(255, 255, 255, 0.08);
    }

    .profile-line div {
      width: 62%;
      height: 100%;
      background: linear-gradient(90deg, #43b8cc, #8cecff);
      box-shadow: 0 0 12px rgba(88, 217, 239, 0.65);
    }

    .footer-hint {
      position: fixed;
      z-index: 8;
      left: 50%;
      bottom: 25px;
      transform: translateX(-50%);
      color: rgba(190, 211, 222, 0.6);
      font-size: 10px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      pointer-events: none;
      white-space: nowrap;
    }

    #loading {
      position: fixed;
      inset: 0;
      z-index: 100;
      display: grid;
      place-items: center;
      background: #071019;
      color: var(--cyan);
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      transition: opacity 500ms ease;
    }

    #loading.hidden {
      opacity: 0;
      pointer-events: none;
    }

    @media (max-width: 900px) {
      .topbar {
        top: 12px;
        left: 12px;
        right: 12px;
      }

      .brand {
        max-width: 58%;
        padding: 13px 15px;
      }

      .subtitle {
        display: none;
      }

      .pill {
        display: none;
      }

      .control-panel {
        left: 12px;
        bottom: 12px;
        width: 245px;
      }

      .profile {
        display: none;
      }

      .footer-hint {
        display: none;
      }
    }

    @media (max-width: 600px) {
      .brand {
        max-width: 75%;
      }

      .control-panel {
        width: 235px;
      }

      .data-grid {
        grid-template-columns: 1fr 1fr;
      }

      .data-item {
        padding: 9px;
      }

      .data-item strong {
        font-size: 14px;
      }
    }
  </style>
</head>

<body>
  <div id="viewport"></div>
  <div class="vignette"></div>

  <header class="topbar">
    <div class="brand">
      <div class="eyebrow">Heavy Systems Test Facility</div>
      <h1>Bogie Roller Test Stand</h1>
      <div class="subtitle">Loaded bogie 02 · sprung heavy-haul configuration · live traction test</div>
    </div>

    <div class="top-actions">
      <div class="pill">
        <span class="pill-label">System</span>
        <span class="pill-value" id="systemStatus">RUNNING</span>
      </div>
      <div class="pill">
        <span class="pill-label">Test Cell</span>
        <span class="pill-value">RC-04 / ACTIVE</span>
      </div>
    </div>
  </header>

  <aside class="panel control-panel">
    <div class="panel-title">
      <span>Test Controls</span>
      <span>Operator</span>
    </div>

    <div class="control-row">
      <label for="speed">Bogie speed</label>
      <input id="speed" type="range" min="0" max="2.2" step="0.05" value="0.7" />
    </div>

    <div class="button-row">
      <button id="runButton" class="primary">Pause Test</button>
      <button id="resetButton">Reset Position</button>
    </div>

    <div class="view-row">
      <button data-view="overview">Overview</button>
      <button data-view="side">Side</button>
      <button data-view="top">Top</button>
    </div>
  </aside>

  <aside class="panel profile">
    <div class="panel-title">
      <span>Live Test Profile</span>
      <span id="profileClock">00:00</span>
    </div>

    <div class="profile-line"><div></div></div>

    <div class="data-grid">
      <div class="data-item">
        <span>Cell load</span>
        <strong id="loadValue">12.4<small> kN</small></strong>
      </div>
      <div class="data-item">
        <span>Axle load</span>
        <strong id="axleValue">6.2<small> kN</small></strong>
      </div>
      <div class="data-item">
        <span>Roller speed</span>
        <strong id="rollerValue">3.2<small> rad/s</small></strong>
      </div>
      <div class="data-item">
        <span>Traction</span>
        <strong id="tractionValue">94<small> %</small></strong>
      </div>
    </div>
  </aside>

  <div class="footer-hint">Drag to orbit · Right-drag to pan · Scroll to zoom · Double-click to reset view</div>
  <div id="loading">Initializing test cell…</div>

  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    const viewport = document.getElementById("viewport");

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x071019);
    scene.fog = new THREE.FogExp2(0x071019, 0.027);

    const camera = new THREE.PerspectiveCamera(
      42,
      innerWidth / innerHeight,
      0.1,
      100
    );

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setSize(innerWidth, innerHeight);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    viewport.appendChild(renderer.domElement);

    const materials = {
      floor: new THREE.MeshStandardMaterial({
        color: 0x111c24,
        roughness: 0.9,
        metalness: 0.12
      }),
      steel: new THREE.MeshStandardMaterial({
        color: 0x52646f,
        roughness: 0.38,
        metalness: 0.78
      }),
      darkSteel: new THREE.MeshStandardMaterial({
        color: 0x26343d,
        roughness: 0.42,
        metalness: 0.82
      }),
      frame: new THREE.MeshStandardMaterial({
        color: 0x344853,
        roughness: 0.34,
        metalness: 0.86
      }),
      roller: new THREE.MeshStandardMaterial({
        color: 0x8b989f,
        roughness: 0.25,
        metalness: 0.92
      }),
      rollerDark: new THREE.MeshStandardMaterial({
        color: 0x53616a,
        roughness: 0.3,
        metalness: 0.9
      }),
      rubber: new THREE.MeshStandardMaterial({
        color: 0x111719,
        roughness: 0.78,
        metalness: 0.08
      }),
      rubberEdge: new THREE.MeshStandardMaterial({
        color: 0x242c2f,
        roughness: 0.65,
        metalness: 0.12
      }),
      yellow: new THREE.MeshStandardMaterial({
        color: 0xe9ad28,
        roughness: 0.48,
        metalness: 0.35
      }),
      orange: new THREE.MeshStandardMaterial({
        color: 0xd96b25,
        roughness: 0.42,
        metalness: 0.42
      }),
      copper: new THREE.MeshStandardMaterial({
        color: 0xb97838,
        roughness: 0.3,
        metalness: 0.8
      }),
      red: new THREE.MeshStandardMaterial({
        color: 0xb92935,
        roughness: 0.36,
        metalness: 0.45
      }),
      white: new THREE.MeshStandardMaterial({
        color: 0xdde6e8,
        roughness: 0.5,
        metalness: 0.25
      }),
      black: new THREE.MeshStandardMaterial({
        color: 0x080d10,
        roughness: 0.6,
        metalness: 0.35
      })
    };

    function addBox(parent, size, position, material, castShadow = true, receiveShadow = true) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(size[0], size[1], size[2]),
        material
      );
      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = castShadow;
      mesh.receiveShadow = receiveShadow;
      parent.add(mesh);
      return mesh;
    }

    function addCylinder(
      parent,
      radiusTop,
      radiusBottom,
      height,
      position,
      material,
      rotation = [0, 0, 0],
      segments = 32
    ) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments),
        material
      );
      mesh.position.set(position[0], position[1], position[2]);
      mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addTorus(parent, radius, tube, position, material, rotation = [0, 0, 0]) {
      const mesh = new THREE.Mesh(
        new THREE.TorusGeometry(radius, tube, 10, 28),
        material
      );
      mesh.position.set(position[0], position[1], position[2]);
      mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
      mesh.castShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // Lighting
    scene.add(new THREE.HemisphereLight(0x9dc9dc, 0x182126, 1.7));

    const keyLight = new THREE.DirectionalLight(0xe8f7ff, 3.1);
    keyLight.position.set(5, 10, 7);
    keyLight.castShadow = true;
    keyLight.shadow.mapSize.set(2048, 2048);
    keyLight.shadow.camera.left = -9;
    keyLight.shadow.camera.right = 9;
    keyLight.shadow.camera.top = 8;
    keyLight.shadow.camera.bottom = -6;
    keyLight.shadow.camera.near = 0.5;
    keyLight.shadow.camera.far = 30;
    keyLight.shadow.bias = -0.00025;
    scene.add(keyLight);

    const rimLight = new THREE.DirectionalLight(0x4cbfe0, 1.6);
    rimLight.position.set(-7, 5, -6);
    scene.add(rimLight);

    const warmLight = new THREE.PointLight(0xffa84d, 18, 12, 2);
    warmLight.position.set(4.5, 2.8, 3.2);
    scene.add(warmLight);

    // Floor and grid
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(40, 40), materials.floor);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.012;
    floor.receiveShadow = true;
    scene.add(floor);

    const grid = new THREE.GridHelper(30, 30, 0x31505d, 0x1b2c35);
    grid.position.y = 0.002;
    grid.material.transparent = true;
    grid.material.opacity = 0.28;
    scene.add(grid);

    // Test cell base
    const testStand = new THREE.Group();
    scene.add(testStand);

    addBox(testStand, [11.6, 0.32, 0.42], [0, 0.22, -1.13], materials.darkSteel);
    addBox(testStand, [11.6, 0.32, 0.42], [0, 0.22, 1.13], materials.darkSteel);

    for (const x of [-5.25, -3.5, -1.75, 0, 1.75, 3.5, 5.25]) {
      addBox(testStand, [0.3, 0.28, 2.75], [x, 0.19, 0], materials.frame);
    }

    // Floor safety boundary
    const safetyMaterial = materials.yellow;
    addBox(testStand, [12.6, 0.035, 0.055], [0, 0.025, -2.35], safetyMaterial, false);
    addBox(testStand, [12.6, 0.035, 0.055], [0, 0.025, 2.35], safetyMaterial, false);
    addBox(testStand, [0.055, 0.035, 4.7], [-6.3, 0.025, 0], safetyMaterial, false);
    addBox(testStand, [0.055, 0.035, 4.7], [6.3, 0.025, 0], safetyMaterial, false);

    // Roller support pedestals
    for (const x of [-4.5, -3, -1.5, 0, 1.5, 3, 4.5]) {
      for (const z of [-0.72, 0.72]) {
        addBox(testStand, [0.42, 0.62, 0.42], [x, 0.67, z], materials.frame);
        addBox(testStand, [0.54, 0.12, 0.54], [x, 0.99, z], materials.darkSteel);

        addCylinder(
          testStand,
          0.19,
          0.19,
          0.28,
          [x, 1.02, z],
          materials.rollerDark,
          [Math.PI / 2, 0, 0]
        );

        addCylinder(
          testStand,
          0.09,
          0.09,
          0.34,
          [x, 1.02, z],
          materials.steel,
          [Math.PI / 2, 0, 0]
        );
      }
    }

    // Roller bank
    const rollers = [];

    for (let i = 0; i < 11; i++) {
      const x = -4.5 + i * 1.125;

      for (const z of [-0.72, 0.72]) {
        const rollerGroup = new THREE.Group();
        rollerGroup.position.set(x, 1.28, z);
        testStand.add(rollerGroup);

        addCylinder(
          rollerGroup,
          0.28,
          0.28,
          1.5,
          [0, 0, 0],
          materials.roller,
          [Math.PI / 2, 0, 0],
          40
        );

        addCylinder(
          rollerGroup,
          0.29,
          0.29,
          0.06,
          [0, 0, 0.78],
          materials.rollerDark,
          [Math.PI / 2, 0, 0]
        );

        addCylinder(
          rollerGroup,
          0.29,
          0.29,
          0.06,
          [0, 0, -0.78],
          materials.rollerDark,
          [Math.PI / 2, 0, 0]
        );

        rollers.push(rollerGroup);
      }
    }

    // Measurement frame
    addBox(testStand, [0.08, 3.35, 0.08], [-5.95, 1.9, 1.43], materials.yellow);
    addBox(testStand, [0.08, 3.35, 0.08], [5.95, 1.9, 1.43], materials.yellow);
    addBox(testStand, [12.0, 0.08, 0.08], [0, 3.58, 1.43], materials.yellow);
    addBox(testStand, [12.0, 0.05, 0.05], [0, 0.36, 1.43], materials.yellow);

    // Drive motor
    const motor = new THREE.Group();
    motor.position.set(5.7, 1.04, 0.94);
    testStand.add(motor);

    addCylinder(motor, 0.43, 0.43, 1.35, [0, 0, 0], materials.darkSteel, [0, 0, Math.PI / 2]);
    addCylinder(motor, 0.48, 0.48, 0.16, [0, 0, 0.72], materials.orange, [0, 0, Math.PI / 2]);
    addCylinder(motor, 0.48, 0.48, 0.16, [0, 0, -0.72], materials.orange, [0, 0, Math.PI / 2]);

    for (let i = 0; i < 7; i++) {
      addTorus(
        motor,
        0.44,
        0.025,
        [0, 0, -0.58 + i * 0.17],
        materials.rollerDark,
        [0, 0, Math.PI / 2]
      );
    }

    addCylinder(motor, 0.18, 0.18, 0.28, [0, 0, 1.02], materials.steel, [0, 0, Math.PI / 2]);

    // End stops
    for (const x of [-5.35, 5.35]) {
      for (const z of [-0.72, 0.72]) {
        addBox(testStand, [0.28, 0.55, 0.35], [x, 0.98, z], materials.yellow);
        addBox(testStand, [0.08, 0.34, 0.18], [x + Math.sign(x) * 0.16, 1.0, z], materials.red);
      }
    }

    // Bogie
    const bogie = new THREE.Group();
    scene.add(bogie);

    // Side frames
    for (const z of [-0.88, 0.88]) {
      addBox(bogie, [5.4, 0.34, 0.24], [0, 2.18, z], materials.frame);
      addBox(bogie, [5.4, 0.1, 0.31], [0, 2.37, z], materials.darkSteel);

      for (const x of [-2.55, 2.55]) {
        addBox(bogie, [0.28, 0.48, 0.28], [x, 2.18, z], materials.darkSteel);
      }

      addCylinder(
        bogie,
        0.075,
        0.075,
        0.05,
        [-2.55, 2.18, z],
        materials.steel,
        [Math.PI / 2, 0, 0]
      );
      addCylinder(
        bogie,
        0.075,
        0.075,
        0.05,
        [2.55, 2.18, z],
        materials.steel,
        [Math.PI / 2, 0, 0]
      );
    }

    // Cross members
    for (const x of [-2.7, -1.35, 0, 1.35, 2.7]) {
      addBox(bogie, [0.2, 0.24, 1.95], [x, 2.18, 0], materials.frame);
    }

    // Axles
    for (const x of [-1.6, 1.6]) {
      addCylinder(
