      } else if (name === "top") {
        target.set(0, 1.15, 0);
        spherical.set(12.5, 0.18, 0.01);
      } else {
        target.set(0, 1.65, 0);
        spherical.set(13.4, 0.91, 0.68);
      }

      updateCamera();
    }

    let userGoal = null;

